      "purpose": "Trusted workflow-only script to project authoritative documents, generate CSPRNG seeds, verify evidence, and manage state transitions.",
      "content": "const fs = require('fs');
const path = require('path');
const crypto = require('crypto');

const ROOT_DIR = path.resolve(__dirname, '..');
const CATALOG_PATH = path.join(ROOT_DIR, 'truth_reader', 'catalog.json');
const SELECTOR_PATH = path.join(ROOT_DIR, 'truth_reader', 'selector.json');
const EVIDENCE_PATH = path.join(ROOT_DIR, 'truth_reader', 'evidence.json');
const STATUS_PATH = path.join(ROOT_DIR, 'truth_reader', 'status.json');
const STATE_PATH = path.join(ROOT_DIR, 'truth_reader', 'state.json');
const PROJECTIONS_DIR = path.join(ROOT_DIR, 'truth_reader', 'projections');

function readJson(filePath) {
  return JSON.parse(fs.readFileSync(filePath, 'utf8'));
}

function writeJson(filePath, data) {
  fs.mkdirSync(path.dirname(filePath), { recursive: true });
  fs.writeFileSync(filePath, JSON.stringify(data, null, 2) + '\n', 'utf8');
}

function generateSeed() {
  return crypto.randomBytes(16).toString('hex');
}

function projectMarkdown(rawContent, seedsCollector) {
  const rawParagraphs = rawContent.split(/\r?\n\r?\n/);
  const records = [];
  let currentTopic = null;

  for (let i = 0; i < rawParagraphs.length; i++) {
    const text = rawParagraphs[i];
    const headingMatch = text.match(/^#{1,6}\s+(.+)$/m);
    if (headingMatch) {
      currentTopic = headingMatch[1].trim();
    }
    records.push({
      index: i,
      topic: currentTopic,
      text: text,
      truth_seed: null
    });
  }

  // Evenly distribute seeds across beginning, middle, and end chunks
  const total = records.length;
  const targetSeedCount = Math.max(3, Math.min(10, Math.ceil(total / 3)));
  const step = Math.max(1, Math.floor(total / targetSeedCount));

  for (let i = 0; i < total; i += step) {
    const seed = generateSeed();
    records[i].truth_seed = seed;
    seedsCollector.push(seed);
    if (seedsCollector.length >= targetSeedCount) break;
  }

  if (records.length > 0 && records[records.length - 1].truth_seed === null) {
    const seed = generateSeed();
    records[records.length - 1].truth_seed = seed;
    seedsCollector.push(seed);
  }

  return records;
}

function projectJson(rawContent, seedsCollector) {
  const parsed = JSON.parse(rawContent);
  const structuralSeeds = [];
  const seedCount = 4;

  for (let i = 0; i < seedCount; i++) {
    const seed = generateSeed();
    seedsCollector.push(seed);
    structuralSeeds.push({
      checkpoint_index: i,
      truth_seed: seed
    });
  }

  // Preserves 100% of current JSON source while attaching distributed seeds
  return {
    projection_format: 'json_complete_preserved',
    source_data: parsed,
    structural_seeds: structuralSeeds
  };
}

function handleGenerate() {
  const catalog = readJson(CATALOG_PATH);
  const selector = readJson(SELECTOR_PATH);
  const selectedDocIds = Object.keys(selector).filter(k => selector[k] === true);

  if (selectedDocIds.length === 0) {
    process.exit(0);
  }

  // Ensure only valid enumerated keys are selected
  for (const docId of selectedDocIds) {
    if (!catalog.documents[docId]) {
      console.error(`Invalid document selector: ${docId}`);
      process.exit(1);
    }
  }

  const expectedSeeds = [];
  fs.mkdirSync(PROJECTIONS_DIR, { recursive: true });

  for (const docId of selectedDocIds) {
    const docMeta = catalog.documents[docId];
    const fullSourcePath = path.join(ROOT_DIR, docMeta.source_path);
    if (!fs.existsSync(fullSourcePath)) {
      console.error(`Authoritative source missing: ${docMeta.source_path}`);
      process.exit(1);
    }

    const rawContent = fs.readFileSync(fullSourcePath, 'utf8');
    let projection;
    if (docMeta.type === 'json') {
      projection = projectJson(rawContent, expectedSeeds);
    } else {
      projection = projectMarkdown(rawContent, expectedSeeds);
    }

    const fullProjPath = path.join(ROOT_DIR, docMeta.projection_path);
    writeJson(fullProjPath, projection);
  }

  writeJson(STATE_PATH, {
    active_docs: selectedDocIds,
    expected_seeds: expectedSeeds
  });

  writeJson(STATUS_PATH, {
    state: 'PROJECTIONS_READY',
    active_docs: selectedDocIds,
    last_verified_at: null
  });

  console.log(`Successfully generated projections for ${selectedDocIds.length} doc(s).`);
}

function handleVerify() {
  const state = readJson(STATE_PATH);
  const evidence = readJson(EVIDENCE_PATH);
  const catalog = readJson(CATALOG_PATH);
  const selector = readJson(SELECTOR_PATH);

  if (!state.expected_seeds || state.expected_seeds.length === 0) {
    console.log('No pending truth reader challenge to verify.');
    process.exit(0);
  }

  const submitted = Array.isArray(evidence.seeds) ? evidence.seeds : [];
  const expected = state.expected_seeds;

  let match = submitted.length === expected.length;
  if (match) {
    for (let i = 0; i < expected.length; i++) {
      if (submitted[i] !== expected[i]) {
        match = false;
        break;
      }
    }
  }

  if (!match) {
    // FAIL is a strict no-op: no mutations, exit with error
    console.error('Evidence verification failed. No state mutated.');
    process.exit(1);
  }

  // PASS: perform atomic cleanup/reset
  for (const docId of Object.keys(selector)) {
    selector[docId] = false;
  }
  writeJson(SELECTOR_PATH, selector);

  writeJson(EVIDENCE_PATH, { seeds: [] });

  // Remove generated projections
  for (const docId of state.active_docs) {
    const docMeta = catalog.documents[docId];
    if (docMeta) {
      const fullProjPath = path.join(ROOT_DIR, docMeta.projection_path);
      if (fs.existsSync(fullProjPath)) {
        fs.unlinkSync(fullProjPath);
      }
    }
  }

  const passedDocs = state.active_docs;
  writeJson(STATE_PATH, {
    active_docs: [],
    expected_seeds: []
  });

  writeJson(STATUS_PATH, {
    state: 'PASS',
    active_docs: [],
    last_verified_at: new Date().toISOString(),
    cleared_docs: passedDocs
  });

  console.log('Evidence verification PASS: cleanup committed.');
}

const mode = process.argv[2];
if (mode === '--generate') {
  handleGenerate();
} else if (mode === '--verify') {
  handleVerify();
} else {
  console.error('Usage: node scripts/truth_reader.js [--generate | --verify]');
  process.exit(1);
}
