      "path": ".github/workflows/truth_reader.yml",
      "purpose": "GitHub Actions workflow to handle doc generation on selector commit and exact seed verification on evidence commit.",
      "content": "name: Truth Reader Verification

on:
  push:
    paths:
      - 'truth_reader/selector.json'
      - 'truth_reader/evidence.json'
    branches:
      - main

permissions:
  contents: write

jobs:
  truth-reader-cycle:
    if: github.actor != 'github-actions[bot]'
    runs-on: ubuntu-latest
    steps:
      - name: Checkout repository
        uses: actions/checkout@v4
        with:
          fetch-depth: 2

      - name: Setup Node.js
        uses: actions/setup-node@v4
        with:
          node-version: 20

      - name: Detect Changed Files
        id: diff
        run: |
          CHANGED=$(git diff --name-only HEAD~1 HEAD)
          echo "changed=$CHANGED" >> $GITHUB_OUTPUT
          if echo "$CHANGED" | grep -q 'truth_reader/evidence.json'; then
            echo "evidence_changed=true" >> $GITHUB_OUTPUT
          else
            echo "evidence_changed=false" >> $GITHUB_OUTPUT
          fi
          if echo "$CHANGED" | grep -q 'truth_reader/selector.json'; then
            echo "selector_changed=true" >> $GITHUB_OUTPUT
          else
            echo "selector_changed=false" >> $GITHUB_OUTPUT
          fi

      - name: Verify Evidence
        if: steps.diff.outputs.evidence_changed == 'true'
        run: |
          node scripts/truth_reader.js --verify
          git config user.name 'github-actions[bot]'
          git config user.email 'github-actions[bot]@users.noreply.github.com'
          git add truth_reader/
          if ! git diff --cached --quiet; then
            git commit -m "[skip ci] Truth reader PASS: atomic cleanup"
            git push
          fi

      - name: Generate Projections
        if: steps.diff.outputs.selector_changed == 'true' && steps.diff.outputs.evidence_changed != 'true'
        run: |
          node scripts/truth_reader.js --generate
          git config user.name 'github-actions[bot]'
          git config user.email 'github-actions[bot]@users.noreply.github.com'
          git add truth_reader/
          if ! git diff --cached --quiet; then
            git commit -m "[skip ci] Truth reader: projections generated"
            git push
          fi
"
    }
  ],
  "design_checks": {
    "authoritative_docs_immutable": true,
    "enumerated_doc_selector": true,
    "projection_from_current_source": true,
    "all_projections_are_json": true,
    "non_json_full_content_preserved": true,
    "distributed_seed_coverage": true,
    "workflow_only_seed_authority": true,
    "exact_complete_seed_match": true,
    "fail_is_noop": true,
    "pass_atomic_cleanup": true,
    "recursive_workflow_loop_prevented": true
  },
  "unresolved_requirements": []
}
